const sliderNumber=(value:number|readonly number[])=>Number(Array.isArray(value)?value[0]:value);
const drawLayer=(ctx:CanvasRenderingContext2D,layer:LayerMeta,surface:LayerSurface,w:number,h:number)=>{let source=surface.pixels;if(layer.hasMask&&layer.maskEnabled&&surface.mask){const temp=makeCanvas(w,h),tc=temp.getContext('2d')!;tc.drawImage(surface.pixels,0,0);tc.globalCompositeOperation='destination-in';tc.drawImage(maskToAlpha(surface.mask),0,0);source=temp}ctx.save();ctx.globalAlpha=layer.opacity/100;ctx.globalCompositeOperation=layer.blend;ctx.filter=`brightness(${layer.brightness??100}%) contrast(${layer.contrast??100}%) saturate(${layer.saturation??100}%) blur(${layer.blur??0}px)`;ctx.translate(layer.x+w/2,layer.y+h/2);ctx.rotate((layer.rotation??0)*Math.PI/180);ctx.scale(layer.scaleX??1,layer.scaleY??1);ctx.drawImage(source,-w/2,-h/2);ctx.restore()};
const applyAdjustment=(ctx:CanvasRenderingContext2D,layer:LayerMeta,w:number,h:number)=>{const source=makeCanvas(w,h);source.getContext('2d')!.drawImage(ctx.canvas,0,0);ctx.save();ctx.globalAlpha=layer.opacity/100;ctx.filter=`brightness(${layer.brightness??100}%) contrast(${layer.contrast??100}%) saturate(${layer.saturation??100}%) blur(${layer.blur??0}px)`;ctx.drawImage(source,0,0);ctx.restore()};

